#include <stdio.h>
#include <string.h>

int is_palindrome(const char *s) {
    int left = 0, right = strlen(s) - 1;
    while (left < right) {
        if (s[left] != s[right]) {
            return 0;
        }
        left++;
        right--;
    }
    return 1;
}

int main() {
    printf("level: %d\n", is_palindrome("level"));
    printf("coding: %d\n", is_palindrome("coding"));
    return 0;
}
